SELECT COUNT(*) as total, COUNT(r.event_schedule->>'event_name') as with_event 
FROM sprint_results sr 
JOIN races r ON sr.matchref = r.rak_id;

SELECT COUNT(*) FROM sprint_results sr 
JOIN races r ON sr.matchref = r.rak_id
WHERE r.event_schedule->'sessions' ? 'sprint';

SELECT COUNT(*) FROM sprint_results sr 
JOIN races r ON sr.matchref = r.rak_id
WHERE r.event_schedule->>'event_name' IS NOT NULL;

SELECT COUNT(*) FROM sprint_results sr 
JOIN races r ON sr.matchref = r.rak_id
WHERE r.event_schedule->'sessions'->>'sprint' IS NOT NULL;

SELECT COUNT(*) FROM sprint_results sr 
JOIN races r ON sr.matchref = r.rak_id
WHERE r.event_schedule->'sessions'->>'sprint' != 'null';

SELECT COUNT(*) FROM sprint_results sr 
JOIN races r ON sr.matchref = r.rak_id
WHERE r.event_schedule->>'event_name' IS NOT NULL AND r.event_schedule->>'event_name' != '';

SELECT COUNT(*) FROM sprint_results sr 
JOIN races r ON sr.matchref = r.rak_id
WHERE r.event_schedule->>'event_name' IS NOT NULL;

SELECT COUNT(*) FROM sprint_results sr 
JOIN races r ON sr.matchref = r.rak_id
WHERE sr.sprint_performance->>'position_label' BETWEEN '0' AND '9';
